  function rpFit() { const sc = document.getElementById('rp-scroll'), p = document.getElementById('rp-paper'); if (sc && p && sc.clientWidth) p.style.zoom = Math.max(0.3, Math.min(2.2, (sc.clientWidth - 4) / (parseFloat(p.dataset.w) || 1034))); }
  window.addEventListener('resize', rpFit);
