  async function render() { await render0(); rpFit(); if (tab === 'calendrier') redrawEditor(); const tb = root.querySelector('.chef-tabs'), on = tb && tb.querySelector('.on'); if (tb && on) tb.scrollLeft = on.offsetLeft - (tb.clientWidth - on.offsetWidth) / 2; }   // V4.12 : l'onglet actif reste visible
