      if (!ps.length || ps.some(po => !po.nom || !durMin(po))) return alert('Chaque poste doit avoir un nom, une heure de début et une heure de fin différentes.');
      const cv = coverage(ps), warn = [];
      if (cv.gaps.length) warn.push('Heures non couvertes : ' + cv.gaps.map(rngTxt).join(', '));
